INSERT INTO landing_revisions(id,label,chrome,seo) VALUES ('40000000-0000-4000-8000-000000000001','Landing hiện tại — cần duyệt nội dung và quyền ảnh','{"announcement":{"lead":"Giải pháp điện mặt trời:","body":" Tư vấn theo nhu cầu và hiện trạng công trình.","actionLabel":"Đặt lịch khảo sát","actionHref":"/khao-sat/","enabled":true},"brand":{"label":"Lúa Xanh Đồng Bằng - Trang chủ","lines":["LÚA XANH","ĐỒNG BẰNG"],"href":"/","logoSlot":"chrome.logo"},"navigation":{"label":"Điều hướng chính","items":[{"label":"Trang chủ","href":"/"},{"label":"Giải pháp","href":"/giai-phap/"},{"label":"Dịch vụ","href":"/dich-vu/"},{"label":"Dự án","href":"/du-an/"},{"label":"Thiết bị","href":"/thiet-bi/"}],"callToAction":{"label":"Khảo sát","href":"/khao-sat/"}},"conversion":{"phoneHref":null,"zaloHref":null,"surveyHref":"/khao-sat/"},"footer":{"columns":[{"title":"Giải pháp & Quy trình","items":[{"label":"Tổng quan các hệ thống","href":"/giai-phap/"},{"label":"Quy trình tổng thầu EPC","href":"/dich-vu/#epc"},{"label":"Hộ gia đình & Biệt thự","href":"/giai-phap/#household"},{"label":"Hộ kinh doanh vừa & nhỏ","href":"/giai-phap/#small-business"},{"label":"Doanh nghiệp & Công nghiệp","href":"/giai-phap/#enterprise"}]},{"title":"Hệ thống & Dịch vụ","items":[{"label":"Về chúng tôi","href":"/#ve-chung-toi"},{"label":"Sản phẩm chính hãng","href":"/thiet-bi/"},{"label":"Dịch vụ trọn gói","href":"/dich-vu/"},{"label":"Dự án thực tế","href":"/du-an/"},{"label":"Hỗ trợ khách hàng","href":"/#faq"}]},{"title":"Liên hệ & Trụ sở","items":[{"label":"13 Đồng Khởi, Phường Ninh Kiều, TP. Cần Thơ"},{"label":"0939 126 974","href":"tel:0939126974"},{"label":"nguyenbang.skyone@gmail.com","href":"mailto:nguyenbang.skyone@gmail.com"},{"label":"Thứ 2 - Thứ 7: 07:30 - 18:00"}]}],"note":"Bản demo giao diện · Lúa Xanh Đồng Bằng"}}'::jsonb,'{"title":"Giải pháp điện mặt trời cho gia đình và doanh nghiệp","description":"Tìm hiểu giải pháp điện mặt trời của Lúa Xanh Đồng Bằng: khảo sát, thiết kế, thi công, vận hành và các công trình đã triển khai.","requestedIndexable":false}'::jsonb);
INSERT INTO landing_sections(revision_id,section_key,position,enabled,content) VALUES ('40000000-0000-4000-8000-000000000001','hero',0,true,'{"title":"ƯƠM MẦM\nNĂNG LƯỢNG","tagline":"Tận tâm · Đồng hành · Chất lượng","description":"Lúa Xanh Đồng Bằng cung cấp giải pháp điện mặt trời từ khảo sát, thiết kế, thi công đến vận hành và bảo trì dài hạn. Mỗi hệ thống được xây dựng dựa trên nhu cầu sử dụng điện, điều kiện công trình và hiệu quả đầu tư thực tế.","primaryAction":{"label":"KHẢO SÁT MIỄN PHÍ","href":"/khao-sat/"},"imageAlt":"Hình minh họa thi công hệ thống điện mặt trời","imageSlot":"hero.image","bottomImageSlot":"hero.bottomImage"}'::jsonb);
INSERT INTO landing_sections(revision_id,section_key,position,enabled,content) VALUES ('40000000-0000-4000-8000-000000000001','partners',1,true,'{"title":"Đối Tác\nChiến Lược","brandsLabel":"Logo các đối tác chiến lược","brands":[{"name":"AIKO","emphasis":false},{"name":"HUAWEI","emphasis":false},{"name":"solis","emphasis":true},{"name":"SMA","emphasis":false},{"name":"LONGi","emphasis":true},{"name":"CanadianSolar","emphasis":false},{"name":"SUNGROW","emphasis":false},{"name":"AESOLAR","emphasis":false},{"name":"Trina Solar","emphasis":true}]}'::jsonb);
INSERT INTO landing_sections(revision_id,section_key,position,enabled,content) VALUES ('40000000-0000-4000-8000-000000000001','solutions',2,true,'{"heading":"GIẢI PHÁP CHUYÊN BIỆT\nCHO TỪNG NHÓM KHÁCH HÀNG","introduction":"Chọn nhóm khách hàng phù hợp để xem những thông tin cần cân nhắc trước khi khảo sát.","items":[{"title":"Giải pháp hộ gia đình","text":"Cân đối theo hóa đơn điện, thói quen sử dụng và điều kiện mái nhà.","icon":"⌂","href":"/giai-phap/#household","actionLabel":"Xem giải pháp ⟶","key":"household","imageSlot":"solutions.household.image"},{"title":"Giải pháp hộ kinh doanh vừa & nhỏ","text":"Xem xét giờ vận hành, phụ tải ban ngày và diện tích mái trước khi đề xuất hệ thống.","icon":"⚙","href":"/giai-phap/#small-business","actionLabel":"Xem giải pháp ⟶","key":"small-business","imageSlot":"solutions.small-business.image"},{"title":"Giải pháp doanh nghiệp & công nghiệp","text":"Khảo sát phụ tải, mặt bằng, yêu cầu kỹ thuật và quy trình phối hợp của công trình.","icon":"▤","href":"/giai-phap/#enterprise","actionLabel":"Xem giải pháp ⟶","key":"enterprise","imageSlot":"solutions.enterprise.image"}]}'::jsonb);
INSERT INTO landing_sections(revision_id,section_key,position,enabled,content) VALUES ('40000000-0000-4000-8000-000000000001','services',3,true,'{"heading":"CHÚNG TÔI CÓ THỂ GIÚP\nBẠN NHỮNG GÌ?","introduction":"Chúng tôi thiết kế và thi công trọn gói hệ thống điện mặt trời, cung cấp thiết bị, hoặc tư vấn mô hình đầu tư phù hợp.","items":[{"title":"EPC trọn gói","href":"/dich-vu/#epc","points":["Tư Vấn & Khảo Sát Hiện Trạng","Thiết kế kỹ thuật chuyên sâu","Thi công & Lắp đặt chuẩn hóa","Cung Cấp Thiết bị","Vận Hành & Bảo Trì (O&M)"],"key":"epc","imageSlot":"services.epc.image"},{"title":"Phân phối và cung ứng thiết bị điện mặt trời.","href":"/dich-vu/#equipment-supply","points":["Tấm pin năng lượng mặt trời","Bộ biến tần","Hệ khung & phụ kiện lắp đặt"],"key":"equipment-supply","imageSlot":"services.equipment-supply.image"},{"title":"Các mô hình tài chính/đầu tư","href":"/dich-vu/#investment-models","points":["Tự sản – tự tiêu","Cho thuê thiết bị","DPPA / bán điện trực tiếp"],"key":"investment","imageSlot":"services.investment.image"}]}'::jsonb);
INSERT INTO landing_sections(revision_id,section_key,position,enabled,content) VALUES ('40000000-0000-4000-8000-000000000001','whyUs',4,true,'{"heading":"VÌ SAO CHỌN LÚA XANH ĐỒNG BẰNG","banner":"GIẢI PHÁP PHÙ HỢP · VẬN HÀNH BỀN VỮNG · GIÁ TRỊ DÀI HẠN","paragraphs":["Lúa Xanh Đồng Bằng lấy an toàn kỹ thuật, chất lượng triển khai và hiệu quả sử dụng thực tế làm nền tảng cho mỗi công trình. Chúng tôi không áp dụng một cấu hình cố định, mà cân nhắc đặc điểm sử dụng điện, điều kiện công trình và mục tiêu của từng khách hàng.","Thông qua quy trình làm việc rõ ràng, thiết bị phù hợp và hỗ trợ sau bàn giao, Lúa Xanh Đồng Bằng hướng đến những hệ thống vận hành ổn định, dễ quản lý và mang lại giá trị lâu dài."],"images":[{"alt":"Hình minh họa hệ thống điện áp mái","key":"primary","imageSlot":"whyUs.primary.image"},{"alt":"Hình minh họa hệ thống điện mặt trời","key":"secondary","imageSlot":"whyUs.secondary.image"},{"alt":"Hình minh họa tấm pin mặt trời","key":"panel","imageSlot":"whyUs.panel.image"}]}'::jsonb);
