INSERT INTO landing_sections(revision_id,section_key,position,enabled,content) VALUES ('40000000-0000-4000-8000-000000000001','faq',8,true,'{"heading":"CÂU HỎI THƯỜNG GẶP","introduction":"Giải đáp các băn khoăn phổ biến của chủ nhà và chủ doanh nghiệp trước khi quyết định đầu tư hệ thống điện mặt trời.","imageAlt":"Hình minh họa tư vấn giải pháp điện mặt trời","actionLabel":"Tìm Hiểu Thêm","actionHref":"/khao-sat/","questions":[{"title":"Hệ thống tấm pin mặt trời có bền không?","text":"Tấm pin thường được nhà sản xuất công bố tuổi thọ khoảng 25–30 năm. Tuổi thọ biến tần và thời hạn bảo hành phụ thuộc từng dòng thiết bị; việc lắp đặt và bảo trì đúng cách giúp hệ thống vận hành ổn định."},{"title":"Mất bao lâu để hệ thống hoàn vốn?","text":"Thời gian hoàn vốn phụ thuộc vốn đầu tư, sản lượng điện, mức sử dụng điện ban ngày và giá điện. Chúng tôi sẽ ước tính riêng cho công trình sau khi khảo sát hiện trạng."},{"title":"Có thể lắp đặt trên mái nhà cũ không?","text":"Có thể, nhưng cần kiểm tra kỹ lưỡng kết cấu mái. Chúng tôi sẽ đánh giá độ bền và đề xuất giải pháp phù hợp trong khảo sát miễn phí."}],"imageSlot":"faq.image"}'::jsonb);
INSERT INTO landing_sections(revision_id,section_key,position,enabled,content) VALUES ('40000000-0000-4000-8000-000000000001','contact',9,true,'{"heading":["Muốn biết nhà bạn có","phù hợp để lắp đặt không?"],"description":"Liên hệ với chúng tôi để được tư vấn ngay.","actionLabel":"Hẹn lịch khảo sát miễn phí","actionHref":"/khao-sat/"}'::jsonb);
